SELECT COUNT(*) FROM ct_gm.t_pl_task
WHERE task_no=#{taskNo} AND is_del=0
AND task_id != #{excludeId}

SELECT COUNT(*) FROM ct_gm.t_pl_task
WHERE prod_plan_id=#{prodPlanId} AND process_stage=#{processStage} AND seq_no=#{seqNo}
  AND ((#{deptId} IS NULL AND dept_id IS NULL) OR dept_id=#{deptId}) AND is_del=0
AND task_id != #{excludeId}

SELECT COALESCE(MAX(seq_no), 0) + 1 FROM ct_gm.t_pl_task
WHERE prod_plan_id=#{prodPlanId} AND process_stage=#{processStage}
  AND ((#{deptId} IS NULL AND dept_id IS NULL) OR dept_id=#{deptId}) AND is_del=0
